package httpsec

import (
	"fmt"
	"slices"
	"strings"
)

// Endpoint is one operation of a built-in endpoint the chain answers, as
// Chain.Endpoints lists it.
//
// An endpoint that answers two methods with different meanings is two
// operations, and so two entries on one path: the saved recovery codes are
// counted by GET and regenerated by POST. Such entries declare the same
// SharesPath.
//
// The record describes the chain and changes nothing it does. Later
// capabilities read it: an OpenAPI document uses OperationID as each
// operation's operationId, and observability uses it as the operation's name.
type Endpoint struct {
	// Methods are the HTTP methods this operation answers, such as
	// ["POST"]. They are never empty.
	Methods []string

	// Path is where the operation answers, resolved under the base path. A
	// segment the operation reads from the path is written {name}, as in
	// "/auth/mfa/verify/{method}"; Match applies to the part before it.
	Path string

	// Match is how the part of Path before its first {…} segment is matched.
	Match PathMatch

	// OtherMethods is what the endpoint does with a request on its path in a
	// method it does not answer.
	OtherMethods MethodPolicy

	// SharesPath is non-empty when the operation declares that it shares its
	// path with other operations of its feature, which declare the same value.
	// The declared sharers are the saved recovery codes, the user's sessions
	// and the provider's consents.
	SharesPath string

	// OperationID names the operation: "scrty." followed by the feature and
	// the step, as in "scrty.sign-in.password". It is a documented contract,
	// the same with or without a base path and stable across releases. The
	// Operation constants list every one.
	OperationID string

	// PlacedBy names the option or setting that places the path, whether the
	// consumer gave it or left it at its default, as in "WithLoginRequestPath"
	// or "WithMFAMethodListing". The provider's endpoints name
	// WithOIDCProviderPath for the endpoint when it was given its own path,
	// and WithOIDCProviderPrefix otherwise; its discovery documents, which the
	// issuer places, name EnableOIDCProvider.
	PlacedBy string

	// Requires is what a request must carry for the operation to serve it.
	Requires Requirement

	// feature is the Enable option of the built-in the operation belongs to,
	// such as "EnableMFA". Operations of one feature may declare a shared
	// path; operations of two may not.
	feature string
}

// PathMatch is how an endpoint matches the request path.
//
// Its zero value is no match kind: every listed entry has one of the named
// kinds.
type PathMatch uint8

// The match kinds.
const (
	// MatchExact matches the path and nothing else.
	MatchExact PathMatch = iota + 1

	// MatchSegment matches the path followed by exactly one non-empty
	// segment, which the endpoint reads: "/sso/login/{provider}".
	MatchSegment

	// MatchSubtree matches the path and everything beneath it. The endpoint
	// answers every request there in its methods, one naming nothing it knows
	// included, which it refuses.
	MatchSubtree
)

// String names the match kind as its constant does.
func (m PathMatch) String() string {
	switch m {
	case MatchExact:
		return "MatchExact"
	case MatchSegment:
		return "MatchSegment"
	case MatchSubtree:
		return "MatchSubtree"
	default:
		return fmt.Sprintf("PathMatch(%d)", uint8(m))
	}
}

// MethodPolicy is what an endpoint does with a request on its path in a
// method it does not answer.
//
// Its zero value is no policy: every listed entry has one of the named ones.
type MethodPolicy uint8

// The other-method policies.
const (
	// PassThrough passes the request on, to the rest of the chain and the
	// application, as though the endpoint were not there.
	PassThrough MethodPolicy = iota + 1

	// Refused answers the request 405 Method Not Allowed. The endpoint claims
	// its path for every method.
	Refused
)

// String names the policy as its constant does.
func (p MethodPolicy) String() string {
	switch p {
	case PassThrough:
		return "PassThrough"
	case Refused:
		return "Refused"
	default:
		return fmt.Sprintf("MethodPolicy(%d)", uint8(p))
	}
}

// Requirement is the least an endpoint itself needs before it serves a
// request.
//
// It is not every state the chain's gates let through: a gate may admit a
// request the endpoint would serve on less, or on a state it does not name.
// Each value's godoc states what it means.
//
// Its zero value is no requirement stated: every listed entry has one of the
// named ones, RequiresNothing included. The numeric values are not a
// contract; compare against the constants.
type Requirement uint8

// The requirements.
const (
	// RequiresNothing serves an anonymous request: a sign-in, a public
	// document, or a request whose credential is in its body, such as a
	// magic link, a recovery token or a signed logout token.
	RequiresNothing Requirement = iota + 1

	// RequiresAuthentication serves any authenticated caller, whatever the
	// mechanism that authenticated it: a session, a bearer token, an API key
	// or Basic credentials. Sign-out declares it.
	RequiresAuthentication

	// RequiresPendingSecondFactor serves a session that owes a second factor.
	RequiresPendingSecondFactor

	// RequiresPendingEnrolment serves a session confined to enrolling a second
	// factor.
	RequiresPendingEnrolment

	// RequiresSession serves a request carrying a session. A gate may let a
	// pending session reach the endpoint, as the gates of enrolment and
	// recovery do for passkey registration; that is the gate's rule, stated
	// in the gate's godoc, and not what the endpoint itself requires.
	RequiresSession

	// RequiresBearer serves a request carrying an access token the provider
	// issued.
	RequiresBearer

	// RequiresClientAuthentication serves a request on which a client of the
	// provider identifies itself as its registration requires. A public
	// client sends only its identifier, and at the token endpoint its PKCE
	// verifier; a confidential client authenticates.
	RequiresClientAuthentication
)

// String names the requirement as its constant does.
func (r Requirement) String() string {
	switch r {
	case RequiresNothing:
		return "RequiresNothing"
	case RequiresAuthentication:
		return "RequiresAuthentication"
	case RequiresPendingSecondFactor:
		return "RequiresPendingSecondFactor"
	case RequiresPendingEnrolment:
		return "RequiresPendingEnrolment"
	case RequiresSession:
		return "RequiresSession"
	case RequiresBearer:
		return "RequiresBearer"
	case RequiresClientAuthentication:
		return "RequiresClientAuthentication"
	default:
		return fmt.Sprintf("Requirement(%d)", uint8(r))
	}
}

// The operation identifiers, one per operation of every built-in endpoint.
// Each is "scrty." followed by the feature and the step. They are a
// documented contract: the same with or without a base path, and stable across
// releases.
const (
	// OperationSignInPassword is password sign-in (EnableFormLogin).
	OperationSignInPassword = "scrty.sign-in.password" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationSignInMagicLinkRequest asks for a magic link (EnableMagicLink).
	OperationSignInMagicLinkRequest = "scrty.sign-in.magic-link.request"
	// OperationSignInMagicLinkRedeem redeems a magic link (EnableMagicLink). It
	// is the endpoint the consumer's confirm page posts the token to, which the
	// base path moves; the confirm page itself is not an endpoint of the chain
	// and is not listed.
	OperationSignInMagicLinkRedeem = "scrty.sign-in.magic-link.redeem"
	// OperationSignInPasskeyBegin begins a passwordless passkey sign-in
	// (EnablePasskeys with WithPasskeyPasswordlessLogin).
	OperationSignInPasskeyBegin = "scrty.sign-in.passkey.begin" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationSignInPasskeyFinish finishes a passwordless passkey sign-in.
	OperationSignInPasskeyFinish = "scrty.sign-in.passkey.finish" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationSignOut is sign-out (EnableLogout).
	OperationSignOut = "scrty.sign-out"

	// OperationSSOLogin starts federated sign-in with a provider
	// (EnableOIDCLogin).
	OperationSSOLogin = "scrty.sso.login"
	// OperationSSOCallback is a provider's callback.
	OperationSSOCallback = "scrty.sso.callback"
	// OperationSSOHandoff redeems a handoff code, while redemption is on.
	OperationSSOHandoff = "scrty.sso.handoff"
	// OperationSSOBackchannelLogout receives a provider's back-channel logout.
	OperationSSOBackchannelLogout = "scrty.sso.backchannel-logout"

	// OperationSessionRenewal renews a session (EnableSessionRenewal).
	OperationSessionRenewal = "scrty.session.renewal"
	// OperationSessionSignals is the session signal stream
	// (EnableSessionSignals).
	OperationSessionSignals = "scrty.session.signals"
	// OperationSessionsList lists the user's sign-ins
	// (EnableSessionManagement).
	OperationSessionsList = "scrty.sessions.list"
	// OperationSessionsEndOthers ends the user's other sign-ins.
	OperationSessionsEndOthers = "scrty.sessions.end-others"
	// OperationSessionsEnd ends one of the user's sign-ins.
	OperationSessionsEnd = "scrty.sessions.end"
	// OperationPasswordChange is the consumer's password change, run by the
	// gate (EnablePasswordChangeGate with WithPasswordChangeEndpoint).
	OperationPasswordChange = "scrty.password.change"

	// OperationMFAChallenge begins a second-factor challenge (EnableMFA).
	OperationMFAChallenge = "scrty.mfa.challenge"
	// OperationMFAVerify verifies a second factor.
	OperationMFAVerify = "scrty.mfa.verify"
	// OperationMFAMethods lists the methods a pending session can use
	// (WithMFAMethodListing).
	OperationMFAMethods = "scrty.mfa.methods"
	// OperationMFAEnrolmentBegin begins enrolling a second factor
	// (EnableMFAEnrolment).
	OperationMFAEnrolmentBegin = "scrty.mfa.enrolment.begin"
	// OperationMFAEnrolmentConfirm confirms an enrolment.
	OperationMFAEnrolmentConfirm = "scrty.mfa.enrolment.confirm"
	// OperationMFAEnrolmentConfirmEmail confirms an enrolment by an emailed
	// code, while email confirmation is on.
	OperationMFAEnrolmentConfirmEmail = "scrty.mfa.enrolment.confirm-email"

	// OperationPasskeysRegisterBegin begins registering a passkey
	// (EnablePasskeys).
	OperationPasskeysRegisterBegin = "scrty.passkeys.register.begin" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationPasskeysRegisterFinish finishes registering a passkey.
	OperationPasskeysRegisterFinish = "scrty.passkeys.register.finish" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationPasskeysRegisterConfirm confirms a registration by a saved
	// code.
	OperationPasskeysRegisterConfirm = "scrty.passkeys.register.confirm" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationPasskeysRegisterConfirmEmail confirms a registration by an
	// emailed code.
	OperationPasskeysRegisterConfirmEmail = "scrty.passkeys.register.confirm-email" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationPasskeysList lists the user's passkeys.
	OperationPasskeysList = "scrty.passkeys.list" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationPasskeysRename renames one of the user's passkeys.
	OperationPasskeysRename = "scrty.passkeys.rename" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationPasskeysRemove removes one of the user's passkeys.
	OperationPasskeysRemove = "scrty.passkeys.remove" //nolint:gosec // G101: an operation identifier, not a credential

	// OperationRecoveryComplete completes an account recovery
	// (EnableAccountRecovery).
	OperationRecoveryComplete = "scrty.recovery.complete"
	// OperationRecoveryStart starts a recovery by issued code, while the core
	// enables issued codes.
	OperationRecoveryStart = "scrty.recovery.start"
	// OperationRecoveryFinish finishes a held recovery, while the core may
	// hold one.
	OperationRecoveryFinish = "scrty.recovery.finish"
	// OperationRecoveryCancel cancels a held recovery, while the core may hold
	// one.
	OperationRecoveryCancel = "scrty.recovery.cancel"
	// OperationRecoveryCodesCount counts the user's saved recovery codes,
	// while the core enables saved codes.
	OperationRecoveryCodesCount = "scrty.recovery.codes.count"
	// OperationRecoveryCodesRegenerate regenerates the user's saved recovery
	// codes, while the core enables saved codes.
	OperationRecoveryCodesRegenerate = "scrty.recovery.codes.regenerate"

	// OperationReauthMethods lists how a session can re-prove itself
	// (EnableReauthentication).
	OperationReauthMethods = "scrty.reauth.methods"
	// OperationReauthChallenge begins a re-authentication challenge.
	OperationReauthChallenge = "scrty.reauth.challenge"
	// OperationReauthVerify verifies a re-authentication challenge.
	OperationReauthVerify = "scrty.reauth.verify"
	// OperationReauthPassword re-proves the password.
	OperationReauthPassword = "scrty.reauth.password" //nolint:gosec // G101: an operation identifier, not a credential

	// OperationKeySet serves the public key set (EnableJWKSEndpoint).
	OperationKeySet = "scrty.key-set"

	// OperationOAuth2Authorize is the provider's authorization endpoint
	// (EnableOIDCProvider).
	OperationOAuth2Authorize = "scrty.oauth2.authorize"
	// OperationOAuth2AuthorizeResume resumes a parked authorization request.
	OperationOAuth2AuthorizeResume = "scrty.oauth2.authorize.resume"
	// OperationOAuth2Token is the provider's token endpoint.
	OperationOAuth2Token = "scrty.oauth2.token" //nolint:gosec // G101: an operation identifier, not a credential
	// OperationOAuth2UserInfo is the provider's UserInfo endpoint.
	OperationOAuth2UserInfo = "scrty.oauth2.userinfo"
	// OperationOAuth2Revoke is the provider's revocation endpoint.
	OperationOAuth2Revoke = "scrty.oauth2.revoke"
	// OperationOAuth2Introspect is the provider's introspection endpoint.
	OperationOAuth2Introspect = "scrty.oauth2.introspect"
	// OperationOAuth2EndSession is the provider's end-session endpoint.
	OperationOAuth2EndSession = "scrty.oauth2.end-session"
	// OperationOAuth2EndSessionConfirm is where the consumer's logout page
	// answers.
	OperationOAuth2EndSessionConfirm = "scrty.oauth2.end-session.confirm"
	// OperationOAuth2ConsentsList lists the user's consents.
	OperationOAuth2ConsentsList = "scrty.oauth2.consents.list"
	// OperationOAuth2ConsentsRevoke revokes the user's consent to one client.
	OperationOAuth2ConsentsRevoke = "scrty.oauth2.consents.revoke"
	// OperationOAuth2OpenIDConfiguration is the OpenID configuration document.
	OperationOAuth2OpenIDConfiguration = "scrty.oauth2.openid-configuration"
	// OperationOAuth2AuthorizationServerMetadata is the OAuth authorization
	// server metadata document (RFC 8414).
	OperationOAuth2AuthorizationServerMetadata = "scrty.oauth2.authorization-server-metadata"
)

// Endpoints lists every operation of every built-in endpoint the chain
// answers, with each path resolved under the base path.
//
// The entries are in the order the chain runs its built-ins, outermost first,
// and within one built-in in the order of its operations. A built-in not
// enabled, or an operation its configuration leaves off, is not listed: the
// handoff without redemption, the recovery start without issued codes. The
// provider's discovery documents are listed at the paths they are served on,
// which the issuer places.
//
// Interceptors the consumer registers are not listed: the chain cannot see
// what they answer. Nor are the pages the consumer serves, such as the
// magic-link confirm page and the provider's login and consent pages: they are
// not endpoints of the chain. A consumer that needs those routes in what it
// builds from this list adds them itself.
//
// Each call returns a fresh copy, the Methods of every entry included, so a
// caller may change what it was given without changing the chain or a later
// list. A chain with no built-in endpoint lists none, as an empty slice.
func (c *Chain) Endpoints() []Endpoint {
	if c == nil {
		return []Endpoint{}
	}

	out := make([]Endpoint, len(c.endpoints))
	for i, e := range c.endpoints {
		e.Methods = slices.Clone(e.Methods)
		out[i] = e
	}

	return out
}

// endpointDeclarer is a registered built-in that answers request paths of its
// own. It declares one entry per operation, read once the paths are resolved
// and the built-in is wired, so the entries name the resolved paths and only
// the operations the configuration enables.
type endpointDeclarer interface {
	endpoints() []Endpoint
}

// collectEndpoints gathers the declarations of every built-in among regs, in
// the order given, which is the chain's: slot, then registration. It refuses a
// declaration missing a field it must carry, so the inventory never lists an
// operation it cannot describe, and one that lists an operation identifier
// twice, which wraps ErrConfig and names the identifier and both settings.
func collectEndpoints(regs []registration) ([]Endpoint, error) {
	out := []Endpoint{}
	first := map[string]Endpoint{}

	for _, r := range regs {
		d, ok := r.interceptor.(endpointDeclarer)
		if !ok {
			continue
		}

		for _, e := range d.endpoints() {
			if err := checkDeclared(e); err != nil {
				return nil, err
			}

			if prior, dup := first[e.OperationID]; dup {
				return nil, newConfigError("the operation %q would be listed twice, placed by %s at %q and by %s at %q; "+
					"an operation identifier appears at most once per chain, so remove one of the two",
					e.OperationID, prior.PlacedBy, prior.Path, e.PlacedBy, e.Path)
			}

			first[e.OperationID] = e

			e.Methods = slices.Clone(e.Methods)
			out = append(out, e)
		}
	}

	return out, nil
}

// checkDeclared refuses an entry that does not describe its operation fully.
// It is the library's own invariant, not a consumer's mistake, so its error
// says so rather than wrapping ErrConfig.
func checkDeclared(e Endpoint) error {
	var missing []string

	if !strings.HasPrefix(e.OperationID, "scrty.") {
		missing = append(missing, "an operation identifier")
	}

	// A method is compared byte for byte with the request's, so one that is
	// not upper-case letters never matches and would hide a collision.
	if len(e.Methods) == 0 || slices.ContainsFunc(e.Methods, notUpperCaseToken) {
		missing = append(missing, "its methods")
	}

	if !strings.HasPrefix(e.Path, "/") {
		missing = append(missing, "a path")
	}

	// A placeholder in an exact path would be compared as literal text.
	if e.Match == MatchExact && strings.Contains(e.Path, "{") {
		missing = append(missing, "a literal path for an exact match")
	}

	if e.Match < MatchExact || e.Match > MatchSubtree {
		missing = append(missing, "a match kind")
	}

	if e.OtherMethods < PassThrough || e.OtherMethods > Refused {
		missing = append(missing, "an other-method policy")
	}

	if e.Requires < RequiresNothing || e.Requires > RequiresClientAuthentication {
		missing = append(missing, "a requirement")
	}

	if e.PlacedBy == "" || e.feature == "" {
		missing = append(missing, "the setting and feature that placed it")
	}

	if len(missing) > 0 {
		return fmt.Errorf("httpsec: internal: the endpoint %q at %q declares no %s",
			e.OperationID, e.Path, strings.Join(missing, ", no "))
	}

	return nil
}

// notUpperCaseToken reports whether m is empty or holds anything but the
// upper-case letters an HTTP method the library declares is written in.
func notUpperCaseToken(m string) bool {
	return m == "" || strings.ContainsFunc(m, func(r rune) bool { return r < 'A' || r > 'Z' })
}

// declare builds one entry of feature, placed by placedBy.
func declare(feature, placedBy, id, path string, match PathMatch, other MethodPolicy, req Requirement,
	methods ...string,
) Endpoint {
	return Endpoint{
		Methods:      methods,
		Path:         path,
		Match:        match,
		OtherMethods: other,
		OperationID:  id,
		PlacedBy:     placedBy,
		Requires:     req,
		feature:      feature,
	}
}

// withSegment is prefix followed by one segment the endpoint reads, written
// {name}. A trailing slash on prefix is set aside, so "/sso/login/" gives
// "/sso/login/{provider}".
func withSegment(prefix, name string) string {
	return strings.TrimSuffix(prefix, "/") + "/{" + name + "}"
}
